    width: 250px;
    height: 50px;
  }

  .nums span {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotate(120deg);
    transform-origin: bottom center;
  }

  .nums span.in {
    transform: translate(-50%, -50%) rotate(0deg);
    animation: goIn 1.5s ease-in-out;
  }

  .nums span.out {
    animation: goOut 0.2s ease-in-out;
  }

  @keyframes goIn {
    0% {
      transform: translate(-50%, -50%) rotate(120deg);
    }

    30% {
      transform: translate(-50%, -50%) rotate(-20deg);
    }

    60% {
      transform: translate(-50%, -50%) rotate(10deg);
    }

    100% {
      transform: translate(-50%, -50%) rotate(0deg);
    }
  }

  @keyframes goOut {
    0% {
      transform: translate(-50%, -50%) rotate(0deg);
    }

    60% {
      transform: translate(-50%, -50%) rotate(20deg);
    }

    100% {
      transform: translate(-50%, -50%) rotate(-120deg);
    }
  }

  #replay {
    background-color: #3498db;
    border-radius: 3px;
    border: none;
    color: aliceblue;
    padding: 5px;
    text-align: center;
    display: inline-block;
    cursor: pointer;
    transition: all 0.3s;
  }

  #replay span {
    cursor: pointer;
    display: inline-block;
    position: relative;
    transition: 0.3s;
  }

  #replay span:after {
    content: '\00bb';
    position: absolute;
    opacity: 0;
    top: 0;
    right: -20px;
    transition: 0.5s;
  }

  #replay:hover span {
    padding-right: 25px;
  }

  #replay:hover span:after {
    opacity: 1;
    right: 0;
  }

