starter.PeriodicTable.css:
/* General Styles */
body {
  font-family: "Arial", sans-serif;
  background: linear-gradient(135deg, #1f4037, #99f2c8);
  color: #fff;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
}

/* Title */
.title {
  font-size: 2.5rem;
  margin-bottom: 1rem;
  text-align: center;
  text-shadow: 2px 2px 4px rgba(0, 0, 0);
}

/* Filters */
.filters {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.filters button {
  background-color: #3b3b3b;
  border: none;
  color: white;
  padding: 10px 20px;
  font-size: 1rem;
  cursor: pointer;
  border-radius: 5px;
  transition: background-color 0.3s, transform 0.2s;
}

.filters button:hover {
  background-color: #6dd5fa;
  transform: translateY(-3px);
}

/* Periodic Table Grid */
.table {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(80px, 1fr));
  gap: 10px;
  max-width: 90%;
  margin: 0 auto;
}

/* Element Box */
.element {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background: rgba(255, 255, 255, 0.1);
  border: 2px solid rgba(255, 255, 255, 0.2);
  border-radius: 10px;
  padding: 10px;
  height: 80px;
  cursor: pointer;
  transition: transform 0.3s, box-shadow 0.3s;
}

.element:hover {
  transform: translateY(-5px);
  box-shadow: 0px 4px 15px rgba(255, 255, 255, 0.5);
}

/* Symbol */
.symbol {
  font-size: 1.5rem;
  font-weight: bold;
  color: #fff;
}

/* Tooltip */
.tooltip {
  position: absolute;
  top: 90%;
  left: 50%;
  transform: translate(-50%, 10%);
  background: rgb(0, 0, 0);
  color: #fff;
  padding: 10px;
  border-radius: 5px;
  box-shadow: 0px 4px 10px rgba(0, 0, 0, 0.3);
  z-index: 100;
  /* opacity: 0; */
  animation: fadeIn 0.3s forwards;
  white-space: nowrap;
  font-size: 0.9rem;
}

.tooltip:after {
  content: "";
  position: absolute;
  top: -10px;
  left: 50%;
  transform: translateX(-50%);
  border-width: 5px;
  border-style: solid;
  border-color: transparent transparent rgba(0, 0, 0) transparent;
}

/* Animations */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translate(-50%, 20%);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 10%);
  }
}

/* Responsive Design */
@media (max-width: 768px) {
  .table {
    grid-template-columns: repeat(auto-fit, minmax(60px, 1fr));
  }

  .element {
    height: 60px;
  }

  .symbol {
    font-size: 1.2rem;
  }

  .tooltip {
    font-size: 0.8rem;
  }
}

solution.App.jsx:
import React, { useState } from "react";
import { elements } from "./elements"; // Import the dataset
import "./PeriodicTable.css";

function App() {
  const [hoveredElement, setHoveredElement] = useState(null);
  const [filter, setFilter] = useState("all");

  const filteredElements =
    filter === "all" ? elements : elements.filter(el => el.category === filter);

  return (
    <div className="periodic-table-container">
      <h1 className="title">Interactive Periodic Table</h1>
      <div className="filters">
        <button onClick={() => setFilter("all")}>All</button>
        <button onClick={() => setFilter("nonmetal")}>Nonmetals</button>
        <button onClick={() => setFilter("noble gas")}>Noble Gases</button>
        <button onClick={() => setFilter("alkali metal")}>Alkali Metals</button>
      </div>
      <div className="table">
        {filteredElements.map(el => (
          <div
            key={el.number}
            className={`element ${
              hoveredElement === el.number ? "hovered" : ""
            }`}
            onMouseEnter={() => setHoveredElement(el.number)}
            onMouseLeave={() => setHoveredElement(null)}
          >
            <div className="symbol">{el.symbol}</div>
            {hoveredElement === el.number && (
              <div className="tooltip">
                <p>Atomic Number: {el.number}</p>
                <p>Name: {el.name}</p>
                <p>Category: {el.category}</p>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;

